def validate_data_structure(data, structure):
    """
    Validates whether the given data conforms to the specified structure.

    :param data: The data to be validated.
    :param structure: A JSON-like string representing the expected structure of the data.
    :return: True if the data matches the structure, False otherwise.
    """
    def validate(data_piece, struct_piece):
        if struct_piece == "null":
            return data_piece is None
        elif struct_piece == "number":
            return isinstance(data_piece, (int, float))
        elif struct_piece == "string":
            return isinstance(data_piece, str)
        elif isinstance(struct_piece, dict):
            if struct_piece.get("type") == "array":
                if not isinstance(data_piece, list):
                    return False
                item_type = struct_piece.get("items", "any")
                return all(validate(item, item_type) for item in data_piece)
            elif struct_piece.get("type") == "object":
                if not isinstance(data_piece, dict):
                    return False
                properties = struct_piece.get("properties", {})
                required = struct_piece.get("required", [])
                if not all(key in data_piece for key in required):
                    return False
                for key, value in data_piece.items():
                    if key in properties and not validate(value, properties[key]):
                        return False
                return True
        return False

    return validate(data, structure)
