class TreeNode:
    def __init__(self, value):
        self.value = value
        self.children = []

class Tree:
    def __init__(self):
        self.root = None

    def insert(self, parent_value, value):
        """
        Inserts a new node with the specified value as a child of the node with parent_value.
        If the tree is empty, the new node becomes the root.
        """
        new_node = TreeNode(value)
        if not self.root:
            self.root = new_node
            return
        parent_node = self._find_node(self.root, parent_value)
        if parent_node:
            parent_node.children.append(new_node)

    def _find_node(self, node, value):
        """
        Helper method to find a node with the specified value.
        """
        if node.value == value:
            return node
        for child in node.children:
            result = self._find_node(child, value)
            if result:
                return result
        return None

    def remove(self, value):
        """
        Removes the node with the specified value from the tree.
        If the node to be removed is the root, the tree becomes empty.
        """
        if not self.root:
            return
        if self.root.value == value:
            self.root = None
            return
        self._remove_helper(self.root, value)

    def _remove_helper(self, node, value):
        """
        Helper method to remove a node with the specified value.
        """
        for child in node.children:
            if child.value == value:
                node.children.remove(child)
                return True
            if self._remove_helper(child, value):
                return True
        return False

    def bfs(self):
        """
        Returns a list of node values in breadth-first order.
        """
        if not self.root:
            return []
        result, queue = [], [self.root]
        while queue:
            current = queue.pop(0)
            result.append(current.value)
            queue.extend(current.children)
        return result

    def dfs(self):
        """
        Returns a list of node values in depth-first order.
        """
        return self._dfs_helper(self.root)

    def _dfs_helper(self, node):
        """
        Helper method to perform depth-first traversal.
        """
        if not node:
            return []
        result = [node.value]
        for child in node.children:
            result.extend(self._dfs_helper(child))
        return result
