def convert_length(length, conversion_factor):
    """
    Converts a given length or sequence of lengths by a specified conversion factor.

    Parameters:
    length (int, float, list, tuple, set): The length value or sequence of values to convert.
    conversion_factor (int, float): The factor by which to convert the length(s).

    Returns:
    int, float, list: The converted length or sequence of lengths.
    str: Error message if input is invalid.
    """
    try:
        if isinstance(length, (int, float)):
            return length * conversion_factor
        elif isinstance(length, (list, tuple, set)):
            result = []
            for item in length:
                if isinstance(item, (int, float)):
                    result.append(item * conversion_factor)
                else:
                    return f"Error: Non-numeric item '{item}' found in the length sequence."
            return result
        else:
            return "Error: Length must be a number or a sequence of numbers."
    except TypeError:
        return "Error: Invalid input types for length and/or conversion factor."
