def convert_data_types(data):
    """
    Recursively processes a nested data structure, converting integers to floats,
    rounding floats to two decimal places, trimming whitespace and capitalizing
    strings, and applying the same rules to dictionaries and lists.

    :param data: A nested data structure consisting of dictionaries, lists, integers, floats, and strings.
    :return: The transformed data structure.
    """
    if isinstance(data, dict):
        return {key: convert_data_types(value) for key, value in data.items()}
    elif isinstance(data, list):
        return [convert_data_types(item) for item in data]
    elif isinstance(data, int):
        return float(data)
    elif isinstance(data, float):
        return round(data, 2)
    elif isinstance(data, str):
        return data.strip().title()
    else:
        return data

def merge_sorted_arrays(arr1, arr2):
    """
    Merges two sorted arrays into a single sorted array.

    :param arr1: First sorted array.
    :param arr2: Second sorted array.
    :return: Merged sorted array.
    """
    merged = []
    i, j = 0, 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1
    merged.extend(arr1[i:])
    merged.extend(arr2[j:])
    return merged

