        return ''

    has_male = False
    has_non_male = False

    for user in users:
        if user['gender'] == 'male':
            has_male = True
        else:
            has_non_male = True

        if has_male and has_non_male:
            return 'seděli'

    if len(users) == 1:
        if users[0]['gender'] == 'male':
            return 'seděl'
        elif users[0]['gender'] == 'female':
            return 'seděla'
        else:
            return 'sedělo'

    if has_male:
        return 'seděli'
    else:
        return 'seděly'
