class Inventory:
    def __init__(self):
        """Initialize an empty dictionary to store items and quantities."""
        self.items = {}

    def add_item(self, name, quantity):
        """Add or update the quantity of the item in the inventory."""
        if name in self.items:
            self.items[name] += quantity
        else:
            self.items[name] = quantity
        print(f"Added {quantity} of {name}. Total: {self.items[name]}")

    def remove_item(self, name, quantity):
        """Remove a certain quantity of an item from the inventory."""
        if name not in self.items:
            print(f"Error: {name} does not exist in inventory.")
            return
        if self.items[name] < quantity:
            print(f"Error: Not enough {name} in inventory to remove {quantity}. Available: {self.items[name]}")
            return
        self.items[name] -= quantity
        if self.items[name] == 0:
            del self.items[name]  # Remove the item from inventory if quantity is zero
        print(f"Removed {quantity} of {name}. Remaining: {self.items[name] if name in self.items else 0}")

    def display_inventory(self):
        """Display all items in the inventory with their quantities."""
        if not self.items:
            print("Inventory is empty.")
        else:
            print("Current Inventory:")
            for name, quantity in self.items.items():
                print(f"{name}: {quantity}")

# Example usage:
