from collections import OrderedDict

def memoize(func, max_capacity=1000):
    """
    Decorator to memoize a function with a fixed capacity cache.
    Evicts the least recently used item when capacity is exceeded.
    """
    cache = OrderedDict()

    def memoized_func(*args):
        """
        Memoized version of the function.
        """
        if args in cache:
            cache.move_to_end(args)
        else:
            result = func(*args)
            cache[args] = result
            if len(cache) > max_capacity:
                cache.popitem(last=False)
        return cache[args]

    return memoized_func

@memoize
def fibonacci(n):
    """
    Computes the nth Fibonacci number using recursion with memoization.
    """
    if n <= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)

# Example usage:
# print(fibonacci(50))  # Should be very fast even for n=50 due to memoization
