def get_new_shape(name: str, shape: tuple, num_heads: int) -> tuple:
    """
    Reshape the tensor based on its name and original shape according to the multi-head attention rules.

    Parameters:
    name (str): The name of the tensor.
    shape (tuple): The original shape of the tensor.
    num_heads (int): The number of attention heads.

    Returns:
    tuple: The new shape of the tensor after reshaping, or None if the tensor does not match any pattern.
    """
    if name == 'output_kernel':
        if shape[0] % num_heads != 0:
            return None
        return (num_heads, shape[0] // num_heads, shape[1])
    elif name == 'output_bias':
        return shape
    elif name in ['query_kernel', 'key_kernel', 'value_kernel']:
        if shape[1] % num_heads != 0:
            return None
        return (shape[0], num_heads, shape[1] // num_heads)
    elif name in ['query_bias', 'key_bias', 'value_bias']:
        if shape[0] % num_heads != 0:
            return None
        return (num_heads, shape[0] // num_heads)
    else:
        return None
